import 'package:firebase_core/firebase_core.dart'  import 'package:firebase_messaging/firebase_messaging.dart'  import 'package:flutter/foundation.dart'  import 'package:flutter_local_notifications/flutter_local_notifications.dart'    /// Firebase Cloud Messaging сервис v8.6  /// Push-уведомления для Мир Самозанятых  /// АНО ЦПС ИНН 9724016805  class FCMService {    static final FCMService _instance = FCMService._internal()    factory FCMService() => _instance    FCMService._internal()      final FirebaseMessaging _messaging = FirebaseMessaging.instance    final FlutterLocalNotificationsPlugin _localNotifications = FlutterLocalNotificationsPlugin()      bool _initialized = false      Future<void> initialize() async {      if (_initialized) return        // Запрос разрешений      final settings = await _messaging.requestPermission(        alert: true,        badge: true,        sound: true,        provisional: false,      )      if (kDebugMode) {        print('FCM permission: ${settings.authorizationStatus}')      }        // Инициализация локальных уведомлений      const androidSettings = AndroidInitializationSettings('@mipmap/ic_launcher')      const iosSettings = DarwinInitializationSettings()      const initSettings = InitializationSettings(        android: androidSettings,        iOS: iosSettings,      )      await _localNotifications.initialize(        initSettings,        onDidReceiveNotificationResponse: (details) {          // Обработка нажатия на уведомление          if (kDebugMode) print('Notification tapped: ${details.payload}')        },      )        // Создание канала для Android      const androidChannel = AndroidNotificationChannel(        'high_importance_channel',        'Важные уведомления',        description: 'Канал для важных уведомлений приложения',        importance: Importance.high,        playSound: true,      )      await _localNotifications        .resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()        ?.createNotificationChannel(androidChannel)        // Получение FCM токена      final token = await _messaging.getToken()      if (kDebugMode) print('FCM Token: $token')        // Обработка сообщений в foreground      FirebaseMessaging.onMessage.listen(_handleForegroundMessage)        // Обработка нажатия на уведомление (app in background)      FirebaseMessaging.onMessageOpenedApp.listen((message) {        if (kDebugMode) print('Message opened app: ${message.data}')      })        // Обработка сообщений в background      FirebaseMessaging.onBackgroundMessage(_firebaseMessagingBackgroundHandler)        _initialized = true    }      void _handleForegroundMessage(RemoteMessage message) {      if (kDebugMode) {        print('Foreground message: ${message.notification?.title}')      }        final notification = message.notification      if (notification != null) {        _showLocalNotification(          id: message.hashCode,          title: notification.title ?? 'Мир Самозанятых',          body: notification.body ?? '',          payload: message.data.toString(),        )      }    }      Future<void> _showLocalNotification({      required int id,      required String title,      required String body,      String? payload,    }) async {      const androidDetails = AndroidNotificationDetails(        'high_importance_channel',        'Важные уведомления',        channelDescription: 'Канал для важных уведомлений приложения',        importance: Importance.high,        priority: Priority.high,        showWhen: true,        icon: '@mipmap/ic_launcher',      )      const iosDetails = DarwinNotificationDetails()      const details = NotificationDetails(        android: androidDetails,        iOS: iosDetails,      )        await _localNotifications.show(id, title, body, details, payload: payload)    }      Future<String?> getToken() async {      return _messaging.getToken()    }      Future<void> subscribeToTopic(String topic) async {      await _messaging.subscribeToTopic(topic)      if (kDebugMode) print('Subscribed to topic: $topic')    }      Future<void> unsubscribeFromTopic(String topic) async {      await _messaging.unsubscribeFromTopic(topic)      if (kDebugMode) print('Unsubscribed from topic: $topic')    }      Future<void> deleteToken() async {      await _messaging.deleteToken()    }  }    /// Обработчик background сообщений  @pragma('vm:entry-point')  Future<void> _firebaseMessagingBackgroundHandler(RemoteMessage message) async {    await Firebase.initializeApp()    if (kDebugMode) {      print('Background message: ${message.notification?.title}')    }  }